#!/bin/bash
out=database/migrations_combined_phpmyadmin.sql
cat > "$out" <<'HEADER'
-- ===========================================================================
-- Pearland411 — combined migrations 0000..0006
-- ===========================================================================
-- Auto-generated by scripts/build_combined_migration.sh from the seven files
-- in database/migrations/.
--
-- USE THIS FILE WHEN IMPORTING THROUGH phpMyAdmin.
-- The original per-file scripts use `DELIMITER //` for stored-procedure
-- guards; some phpMyAdmin versions can't parse that directive. This combined
-- file has those lines stripped (replaced with semicolons) so phpMyAdmin
-- Import accepts it as-is.
--
-- IMPORT STEPS (phpMyAdmin):
--   1. Take a full backup of the `pearlan_new` database first.
--      (Export → Custom → Go.)
--   2. Select the `pearlan_new` database in the left rail.
--   3. Import tab → Choose File → pick this combined file → Go.
--   4. Wait for "Import has been successfully finished".
--
-- IMPORT STEPS (mysql CLI alternative):
--   mysql -u <user> -p pearlan_new < migrations_combined_phpmyadmin.sql
--
-- ROLLBACK
--   If anything looks wrong, restore from the backup you took in step 1.
--
-- IDEMPOTENCY
--   Every section is idempotent where MySQL allows — re-running this file
--   on an already-migrated database is safe (column-add guards skip, seed
--   INSERTs use NOT EXISTS, CREATE TABLE uses IF NOT EXISTS).
-- ===========================================================================

SET SQL_MODE = '';
SET FOREIGN_KEY_CHECKS = 0;

HEADER

for f in database/migrations/0000_schema_fixups.sql \
         database/migrations/0001_auth_flows.sql \
         database/migrations/0002_services.sql \
         database/migrations/0003_newsletter_campaigns.sql \
         database/migrations/0004_rate_limits.sql \
         database/migrations/0005_admin_roles.sql \
         database/migrations/0006_ad_zones.sql; do
    name=$(basename "$f")
    {
        echo ""
        echo "-- ============================================================"
        echo "-- $name"
        echo "-- ============================================================"
        echo ""
        # Strip DELIMITER directives + replace `END //` / standalone `//` lines
        # with semicolons so the procedure body is a single statement when
        # phpMyAdmin parses with the default `;` delimiter.
        sed -E \
            -e '/^DELIMITER /d' \
            -e 's/END[[:space:]]*\/\//END;/g' \
            -e 's/^[[:space:]]*\/\/[[:space:]]*$/;/g' \
            "$f"
    } >> "$out"
done

cat >> "$out" <<'FOOTER'

SET FOREIGN_KEY_CHECKS = 1;
FOOTER

echo "Wrote $out ($(wc -l < "$out") lines)"
